  "BJT-O-0056": [
    "選項本義：意思：確認活動內容是否符合主題。\n本題判定：錯誤。\n錯誤原因：日文本身：此選項本身為自然且成立的日文。\n正常使用：在品質管理、企劃或專案檢討中，確認活動內容與主題／方針的一致性是自然用法。\n例：各部門長は活動内容がテーマに沿っているか確認する。\n錯誤類型：READING_ACTOR_MISMATCH",
    "選項本義：意思：製作發表者與內容清單。\n本題判定：正確。\n正解理由：日文本身：此選項本身為自然且成立的日文。\n正常使用：「リストを作成する」是標準商務搭配，可用於名單、清單、報告資料等。\n例：参加者リストを作成する。",
    "選項本義：意思：核准發表者與內容清單。\n本題判定：錯誤。\n錯誤原因：日文本身：此選項本身為自然且成立的日文。\n正常使用：「資料／申請書を決裁する」本身是正確日文，主語通常是具正式批准權限的主管。\n例：部長が申請書を決裁する。 ／ 担当者が部長の決裁をとる。\n錯誤類型：READING_ROLE_DIRECTION_MISMATCH, BUSINESS_APPROVAL_DIRECTION",
    "選項本義：意思：準備大會議室。\n本題判定：錯誤。\n錯誤原因：日文本身：此選項本身為自然且成立的日文。\n正常使用：活動或會議負責人準備會議室是自然且常見的工作表達。\n例：担当者が大会議室の準備をする。\n錯誤類型：READING_UNSUPPORTED_INFERENCE"
  ],
  "BJT-O-0057": [
    "選項本義：意思：確認會議出席者是否出席。\n本題判定：錯誤。\n錯誤原因：日文本身：此選項本身為自然且成立的日文。\n正常使用：會議前確認出欠是標準工作表達，常用「出欠を確認する／おさえる」。\n例：会議の出欠を確認しておく。\n錯誤類型：READING_PRIORITY_MISMATCH",
    "選項本義：意思：影印董事會資料。\n本題判定：錯誤。\n錯誤原因：日文本身：此選項本身為自然且成立的日文。\n正常使用：「資料をコピーする」本身自然，可直接執行或交代他人執行。\n例：役員会資料を30部コピーする。\n錯誤類型：READING_PRIORITY_MISMATCH, READING_ACTOR_NUANCE",
    "選項本義：意思：請部長審閱原稿。\n本題判定：正確。\n正解理由：日文本身：此選項本身為自然且成立的日文。\n正常使用：「人に～てもらう」表示請對方替自己做某事；「原稿を見てもらう」常表示請上司審閱。\n例：部長に企画書を見てもらう。",
    "選項本義：意思：把原稿翻譯成英文。\n本題判定：錯誤。\n錯誤原因：日文本身：此選項本身為自然且成立的日文。\n正常使用：「原稿を英語に翻訳する」是正確日文，適用於自己或指定翻譯者進行翻譯。\n例：契約書を英語に翻訳する。 ／ 原稿を英訳に出す。\n錯誤類型：READING_DEPENDENCY_MISMATCH, READING_ACTION_NUANCE"
  ],
  "BJT-O-0058": [
    "選項本義：意思：會場布置。\n本題判定：錯誤。\n錯誤原因：日文本身：此選項本身為自然且成立的日文。\n正常使用：「会場のセッティングをする」是自然的活動準備表達。\n例：前日に会場のセッティングを行う。\n錯誤類型：READING_TIME_MISMATCH",
    "選項本義：意思：準備要發放的資料／物品。\n本題判定：錯誤。\n錯誤原因：日文本身：此選項本身為自然且成立的日文。\n正常使用：「配付物を準備する」是自然的商務／活動用語。\n例：企画課が配付物を準備する。\n錯誤類型：READING_ACTOR_MISMATCH",
    "選項本義：意思：說明商品特色。\n本題判定：錯誤。\n錯誤原因：日文本身：此選項本身為自然且成立的日文。\n正常使用：「商品の特徴を説明する／商品の特徴説明」均是自然的銷售展示表達。\n例：展示会で商品の特徴を説明する。\n錯誤類型：READING_ACTOR_MISMATCH",
    "選項本義：意思：接受商品訂單。\n本題判定：正確。\n正解理由：日文本身：此選項本身為自然且成立的日文。\n正常使用：「受注する」是賣方接受客戶訂單的標準商務詞，與「注文受付」同義。\n例：展示会で商品の注文を受け付ける。 ／ 新規案件を受注する。"
  ],
  "BJT-O-0059": [
    "選項本義：意思：改為現金交易。\n本題判定：錯誤。\n錯誤原因：日文本身：此選項本身為自然且成立的日文。\n正常使用：「手形取引から現金取引に変更する」是自然商務表達，用於付款方式變更。\n例：支払方法を現金取引に変更する。\n錯誤類型：READING_TIME_STATUS_MISMATCH",
    "選項本義：意思：把以前提出的價格打折。\n本題判定：錯誤。\n錯誤原因：日文本身：此選項本身為自然且成立的日文。\n正常使用：「価格を値引きする」是自然銷售表達，指降低既有價格。\n例：提示価格から5％値引きする。\n錯誤類型：READING_IMPORTANCE_MISMATCH, READING_ACTION_NUANCE",
    "選項本義：意思：報告對客訴的處理體制。\n本題判定：錯誤。\n錯誤原因：日文本身：此選項本身為自然且成立的日文。\n正常使用：「苦情に対する処理体制を報告する」本身成立，適用於說明客訴處理機制。\n例：苦情処理の体制を取引先に報告する。\n錯誤類型：READING_FOCUS_MISMATCH, READING_IMPORTANCE_MISMATCH",
    "選項本義：意思：討論產品開發。\n本題判定：正確。\n正解理由：日文本身：此選項本身為自然且成立的日文。\n正常使用：「製品開発について話し合う」是自然的企業協作表達。\n例：両社で新製品開発について話し合う。"
  ],
  "BJT-O-0060": [
    "選項本義：意思：全面廢除。\n本題判定：錯誤。\n錯誤原因：日文本身：此選項本身為自然且成立的日文。\n正常使用：「制度を全面的に廃止する」是自然且正式的政策／制度表達。\n例：紙の申請制度を全面的に廃止する。\n錯誤類型：READING_SCOPE_MISMATCH, READING_EXCEPTION_IGNORED",
    "選項本義：意思：只對管理職廢除。\n本題判定：錯誤。\n錯誤原因：日文本身：此選項本身為自然且成立的日文。\n正常使用：「管理職のみ制度を廃止する」是文法與搭配都成立的表達。\n例：管理職のみ対象制度を廃止する。\n錯誤類型：READING_SCOPE_MISMATCH, READING_FUTURE_DIRECTION_IGNORED",
    "選項本義：意思：只對一般職導入。\n本題判定：錯誤。\n錯誤原因：日文本身：此選項本身為自然且成立的日文。\n正常使用：「制度を一般職にのみ導入する」本身完全成立，表示只在一般職開始採用制度。\n例：新しい評価制度を一般職にのみ導入する。\n錯誤類型：READING_DIRECTION_REVERSAL",
    "選項本義：意思：只對有特殊情況的員工實施。\n本題判定：正確。\n正解理由：日文本身：此選項本身為自然且成立的日文。\n正常使用：「事情のある社員にのみ制度を導入する」是正確日文；若制度原本已存在，更精確可說「継続して適用する」。\n例：育児中の社員にフレックスタイム制度を導入する。 ／ 特別な事情のある社員には継続して適用する。"
  ],
