    "選項本義：意思：事先重新啟動。\n本題判定：正確。\n正解理由：日文本身：此選項本身為自然且成立的日文。\n正常使用：「PCを再起動しておく」是標準 IT 用語，表示為後續作業先 restart。\n例：更新前にPCを再起動しておく。",
    "選項本義：意思：事先把電源關掉。\n本題判定：錯誤。\n錯誤原因：日文本身：此選項本身為自然且成立的日文。\n正常使用：「電源を切っておく」本身完全自然，常用於長時間不使用設備時。\n例：長期間使用しない場合は電源を切っておく。\n錯誤類型：READING_NEGATION_REVERSAL",
    "選項本義：意思：事先發送郵件。\n本題判定：錯誤。\n錯誤原因：日文本身：此選項本身為自然且成立的日文。\n正常使用：「メールを発信する」是成立的正式／系統通知用語；日常也常說「メールを送る」。\n例：システムから通知メールを発信する。\n錯誤類型：READING_NEGATION_MISMATCH, READING_ACTOR_MISMATCH"
