    "選項本義：字面是「對條件指出難點／問題點」；難点＝缺點、問題點。\n本題判定：錯誤。\n錯誤原因：本題的正確判斷是「条件に難色を示した」。「難色を示す」＝提案や条件に対して、受け入れにくい態度を示す。動詞は「示す」が定番。 易混點：× 難色を出す／付ける。",
